        translation(itemKey(RecastingItems.LAPIS_MEDIUM_SOUL_CUBE), "靛蓝色的庸魂立方体", "Indigo Medium Soul Cube");
        translation(itemKey(RecastingItems.REDSTONE_MEDIUM_SOUL_CUBE), "赤红色的庸魂立方体", "Scarlet Medium Soul Cube");
        translation(itemKey(RecastingItems.FROST_VORTEX_CORE), "霜璇核心", "Frost Vortex Core");
        translation(itemKey(RecastingItems.SANDALWOOD_RHYME_CORE), "檀韵核心", "Sandalwood Rhyme Core");
        translation(itemKey(RecastingItems.BLAZING_FLAME_CORE), "燎焰核心", "Blazing Flame Core");
        translation(itemKey(RecastingItems.ILLUMINATING_TRUTH_CORE), "照谛核心", "Illuminating Truth Core");
        translation(itemKey(RecastingItems.ABYSS_DEPTH_CORE), "冥渊核心", "Abyss Depth Core");
        translation(itemKey(RecastingItems.DETONATION_PHASE_TRANSITION), "爆燃相变", "Detonation Phase Transition");
        translation(itemKey(RecastingItems.BURNING_PHASE_TRANSITION), "燃烧相变", "Burning Phase Transition");
        translation(itemKey(RecastingItems.BLIND_PHASE_TRANSITION), "致盲相变", "Blind Phase Transition");
        translation(itemKey(RecastingItems.FIRE_TOXIN_PHASE_TRANSITION), "火毒相变", "Fire Toxin Phase Transition");
        translation(itemKey(RecastingItems.SPREAD_PHASE_TRANSITION), "蔓延相变", "Spread Phase Transition");
        translation(itemKey(RecastingItems.REFRACTION_PHASE_TRANSITION), "折射相变", "Refraction Phase Transition");
        translation(itemKey(RecastingItems.CONCEALED_EDGE_PHASE_TRANSITION), "藏锋相变", "Concealed Edge Phase Transition");
        translation(itemKey(RecastingItems.WINDING_PHASE_TRANSITION), "缠绕相变", "Winding Phase Transition");
        translation(itemKey(RecastingItems.EROSION_PHASE_TRANSITION), "侵蚀相变", "Erosion Phase Transition");
        translation(itemKey(RecastingItems.INTERLACE_PHASE_TRANSITION), "交错相变", "Interlace Phase Transition");
        translation(itemDescKey(RecastingItems.OBSESSION_FLAME), "躁动不定的橘红色，焰心处有苍白闪烁。", "Restless orange-red, with pale flashes at the core.");
        translation(itemDescKey(RecastingItems.MEMORY_FLAME), "半透明的琉璃色，焰苗中浮动着朦胧的光影。", "Translucent glazed color, with hazy light and shadow floating in the flame.");
        translation(itemDescKey(RecastingItems.SIN_FLAME), "污浊的暗红色，带有不祥的黑色脉纹，燃烧时散发焦臭。", "Foul dark red with ominous black veins, emitting a charred stench when burning.");
        translation(itemDescKey(RecastingItems.HOLY_FLAME), "纯净的乳白色光焰，边缘环绕着淡淡的金色光晕。", "Pure milky white flame, surrounded by a faint golden halo at the edges.");
        translation(itemDescKey(RecastingItems.CHAOS_FLAME), "色彩无定，在同一秒内可能呈现光谱上的任何颜色。", "Indeterminate colors, may display any color on the spectrum within the same second.");
        translation(itemDescKey(RecastingItems.OTHER_SHORE_FLAME), "冰冷的青白色，摇曳如烛，无温度。", "Cold bluish-white, flickering like a candle, without warmth.");
        translation(itemDescKey(RecastingItems.POETRY_ASH_FLAME), "朦胧的月白色，焰心跃动着如文字般的淡金符文。", "Hazy moon-white, with pale golden runes dancing like text at the core.");
        translation(itemDescKey(RecastingItems.MIRAGE_FLAME), "折射的虹彩色，边缘模糊，仿佛隔着一层水汽。", "Refracted rainbow colors with blurred edges, as if seen through a layer of mist.");
        translation(itemDescKey(RecastingItems.CRAFTSMAN_FLAME), "沉稳的铜黄色，焰形规整，时有金属光泽闪过。", "Steady bronze-yellow with regular flame shape, occasionally flashing with metallic luster.");
        translation(itemDescKey(RecastingItems.ICE_CORE_FLAME), "外层是炽热的亮蓝色，内核却是深邃的、仿佛能吸收光线的绝对暗蓝。", "Outer layer is blazing bright blue, but the core is deep, absolute dark blue that seems to absorb light.");
        translation(itemDescKey(RecastingItems.KARMA_FLAME), "无形的透明之火，只有当它烧灼命运丝线时，才会泛起密麻交错的银线与血线。", "Invisible transparent fire, only revealing densely interwoven silver and blood-red threads when burning the threads of fate.");
        translation(itemDescKey(RecastingItems.CRADLE_FLAME), "柔和的鹅黄色，光芒如同最安稳的烛光，令人心生宁静。", "Soft goose-yellow, its light like the most peaceful candlelight, bringing tranquility to the heart.");
        translation(itemDescKey(RecastingItems.ABYSS_FLAME), "纯粹的哑光黑色，吞噬周围光线，形成一片无声的黑暗区域。", "Pure matte black that devours surrounding light, forming a silent dark region.");
        translation(itemDescKey(RecastingItems.ROYAL_FLAME), "威严的暗金色与深紫色交织，焰形升腾如帝王冠冕。", "Majestic dark gold and deep purple interwoven, the flame rising like an imperial crown.");
        translation(itemDescKey(RecastingItems.OUROBOROS_FLAME), "一种自我吞噬的莫比乌斯环状焰流，颜色在银灰与暗蓝间循环。", "A self-devouring Möbius ring-shaped flame flow, cycling between silver-gray and dark blue.");
        translation(itemDescKey(RecastingItems.MIRROR_FLAME), "如水银般高度反光的镜面之色，完美映照出它所\"模仿\"之火的外貌。", "Highly reflective mirror-like color like mercury, perfectly reflecting the appearance of the flame it 'imitates'.");
        translation(itemDescKey(RecastingItems.LAST_WORDS_FLAME), "琥珀金色，焰心深处封存着一点即将消散的、代表生命最后色彩的星芒。", "Amber gold, with a fading starlight representing life's final color sealed deep in the core.");
        translation(itemDescKey(RecastingItems.TIDE_FLAME), "随着涨落，颜色从新月时的深紫，到满月时如海浪泡沫般的银白。", "With the ebb and flow, colors shift from deep purple at new moon to silvery white like sea foam at full moon.");
        translation(itemDescKey(RecastingItems.FROST_VORTEX_CORE), "冰蓝与银白在核内缓缓旋流，触之生寒。", "Ice-blue and silver swirl slowly within, cold to the touch.");
        translation(itemDescKey(RecastingItems.SANDALWOOD_RHYME_CORE), "暖褐檀香色的光韵在核内回旋，气息沉静。", "Warm sandalwood-hued light circles within, calm and still.");
        translation(itemDescKey(RecastingItems.BLAZING_FLAME_CORE), "赤橙焰心被封于核中，灼热却不外溢。", "A scarlet-orange flame heart sealed within, scorching yet contained.");
        translation(itemDescKey(RecastingItems.ILLUMINATING_TRUTH_CORE), "乳白金辉自核心透出，澄澈而不刺眼。", "Milky golden light seeps from the core, clear yet gentle.");
        translation(itemDescKey(RecastingItems.ABYSS_DEPTH_CORE), "哑光幽黑吞没周围微光，核心深处偶有紫芒一闪。", "Matte abyss-black swallows faint light, with rare purple flashes deep within.");
        translation(itemDescKey(RecastingItems.DETONATION_PHASE_TRANSITION), "赤焰与霜蓝在晶内猛烈交缠，时有爆裂的光点迸出。", "Scarlet flame and frost-blue clash violently within, with bursts of light.");
        translation(itemDescKey(RecastingItems.BURNING_PHASE_TRANSITION), "暖褐檀韵被赤焰裹挟，缓缓渗出焦香般的光晕。", "Warm sandalwood rhyme wrapped in scarlet flame, seeping a scorched glow.");
        translation(itemDescKey(RecastingItems.BLIND_PHASE_TRANSITION), "金辉被燎焰灼白，晶面耀得令人不敢直视。", "Golden radiance burned white by blaze, too bright to look upon.");
        translation(itemDescKey(RecastingItems.FIRE_TOXIN_PHASE_TRANSITION), "幽紫毒雾自赤焰缝隙渗出，黏稠而令人不安。", "Violet toxin haze seeps from scarlet cracks, thick and unsettling.");
        translation(itemDescKey(RecastingItems.SPREAD_PHASE_TRANSITION), "霜纹沿檀色脉络蔓延，如冰霜爬上枯枝。", "Frost patterns spread along sandalwood veins like ice on bare branches.");
        translation(itemDescKey(RecastingItems.REFRACTION_PHASE_TRANSITION), "冰蓝光在乳白晶面折返，碎成细碎虹影。", "Ice-blue light refracts on milky crystal, scattering into faint rainbows.");
        translation(itemDescKey(RecastingItems.CONCEALED_EDGE_PHASE_TRANSITION), "锋芒藏入幽黑与霜蓝之间，只余一线冷光。", "An edge hidden between abyss and frost, leaving only a thin cold gleam.");
        translation(itemDescKey(RecastingItems.WINDING_PHASE_TRANSITION), "金丝与檀纹彼此缠绕，拉出细长的光缆。", "Gold threads and sandalwood lines wind together into slender cords of light.");
        translation(itemDescKey(RecastingItems.EROSION_PHASE_TRANSITION), "檀色被幽黑一点点啃蚀，边缘呈腐蚀般的暗斑。", "Sandalwood hue bitten away by abyss-black, edges mottled like corrosion.");
        translation(itemDescKey(RecastingItems.INTERLACE_PHASE_TRANSITION), "金白与幽紫交错层叠，明暗在同一面晶上撕扯。", "Gold-white and violet layers interlace, light and dark tearing across the crystal.");
