        translation(slashArtKey(SlashArtsRegistry.BLADE_STORM), "剑刃风暴", "Blade Storm");
        translation(slashArtKey(SlashArtsRegistry.BLADE_STORM_LAMBDA), "^剑刃风暴", "Blade Storm Lambda");
        translation(slashArtKey(SlashArtsRegistry.ZANTETSUDEN_MAX), "斩铁式·极", "Zantetsuden Max");
