        translation(slashArtKey(SlashArtsRegistry.LASER_2), "光棱射线[脉冲]", "Prism Beam [Pulse]");
        translation(slashArtKey(SlashArtsRegistry.LASER_3), "光棱射线[连射]", "Prism Beam [Barrage]");
